import java.nio.file.Files;
import java.nio.file.Path;

public class Main {
    public static void main(String[] args) throws Exception {
        Path 门牌 = Path.of("还没建的账本.txt");

        if (!Files.exists(门牌)) {
            Files.writeString(门牌, "狸花 的账本\n");
        }

        System.out.println(Files.readString(门牌));
    }
}

